JS = "(()=>{'use strict';const K='teachers-g9-u1-v1', $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let state={checks:{},answers:{},visits:[],backup:[]},storage=true;try{const p=JSON.parse(localStorage.getItem(K)||'null');if(p&&typeof p==='object')state={...state,...p};}catch(e){storage=false;}function say(t){if($('#status'))$('#status').textContent=t;}function save(){try{localStorage.setItem(K,JSON.stringify(state));}catch(e){storage=false;say('לא ניתן לשמור בדפדפן הזה. אפשר להמשיך לעבוד ללא שמירה.');}}function paint(){$$('[data-meeting]').forEach(m=>{const c=[...m.querySelectorAll('input[type=checkbox]')];m.querySelector('[data-meeting-progress]').textContent=c.filter(x=>x.checked).length+' / '+c.length+' משימות הושלמו';});const ids=new Set(state.visits.map(x=>x.href));$$('a[data-track]').forEach(a=>a.classList.toggle('opened',ids.has(a.getAttribute('href'))));if($('#progress'))$('#progress').textContent=$$('.meeting input[type=checkbox]').filter(el=>el.checked).length+' משימות סומנו כהושלמו במכשיר הזה';if($('#last-opened'))$('#last-opened').textContent=state.visits.length?'נפתח לאחרונה: '+state.visits[state.visits.length-1].label:'עדיין לא נפתחו חומרי לימוד מן היחידה.';if($('#restore-history'))$('#restore-history').disabled=!state.backup.length;}\n$$('[data-save]').forEach(el=>{const key=el.dataset.save;if(el.type==='checkbox'){el.checked=!!state.checks[key];el.addEventListener('change',()=>{state.checks[key]=el.checked;save();paint();});}else{el.value=state.answers[key]||'';el.addEventListener('input',()=>{state.answers[key]=el.value;save();});}});\n$$('a[data-track]').forEach(a=>a.addEventListener('click',()=>{state.visits.push({href:a.getAttribute('href'),label:a.textContent.trim(),at:new Date().toISOString()});state.visits=state.visits.slice(-100);save();paint();}));if($('#reset-history'))$('#reset-history').onclick=()=>{if(!state.visits.length)return say('אין היסטוריית פתיחת קישורים לאיפוס.');state.backup=[...state.visits];state.visits=[];save();paint();say('אופסה היסטוריית הקישורים בלבד. התשובות והשלמת המשימות נשמרו.');};if($('#restore-history'))$('#restore-history').onclick=()=>{state.visits=[...state.backup,...state.visits].slice(-100);state.backup=[];save();paint();say('היסטוריית פתיחת הקישורים שוחזרה.');};\n$$('[data-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-copy]').forEach(b=>b.onclick=async()=>{const text=new URL(b.dataset.copy,location.href).href;try{await navigator.clipboard.writeText(text);say('הקישור הועתק.');}catch(e){say('לא ניתן להעתיק אוטומטית. העתיקו את הקישור משורת הכתובת.');}});\nif($('#writing')){const update=()=>{const t=$('#writing').value.trim(),n=(t.match(/\\S+/g)||[]).length;$('#word-count').textContent=n+' / 70–100 words';$('#writing-preview').replaceChildren();t.split(/\\n+/).filter(Boolean).forEach(line=>{const p=document.createElement('p'),b=document.createElement('b'),s=document.createElement('span');b.textContent=(line.match(/\\S+/g)||[]).length;s.textContent=line;p.append(b,s);$('#writing-preview').append(p);});};$('#writing').addEventListener('input',update);update();}\nconst slides=$$('.deck-slide');let deckIndex=0;function showDeck(i){deckIndex=Math.max(0,Math.min(i,slides.length-1));slides.forEach((s,j)=>{s.classList.toggle('active',j===deckIndex);s.setAttribute('aria-hidden',j!==deckIndex?'true':'false');});if($('#deck-count'))$('#deck-count').textContent=(deckIndex+1)+' / '+slides.length;if($('#deck-prev'))$('#deck-prev').disabled=deckIndex===0;if($('#deck-next'))$('#deck-next').disabled=deckIndex===slides.length-1;if(slides.length)history.replaceState(null,'','#slide-'+(deckIndex+1));}\nlet moveVocab=null;if(slides.length){const n=Number((location.hash.match(/slide-(\\d+)/)||[])[1]||1);showDeck(n-1);$('#deck-prev').onclick=()=>showDeck(deckIndex-1);$('#deck-next').onclick=()=>showDeck(deckIndex+1);}\nif($('#vocab')){fetch('vocab.json').then(r=>{if(!r.ok)throw Error('Vocabulary unavailable');return r.json();}).then(all=>{const f=JSON.parse($('#focus-words').textContent);const params=new URLSearchParams(location.search);const start=Number(params.get('start')),end=Number(params.get('end'));const scoped=Number.isInteger(start)&&Number.isInteger(end)&&start>=1&&end>=start&&end<=all.length;if(scoped){const option=new Option('טווח '+start+'–'+end,'range',true,true);$('#v-group').add(option);}else{$('#v-group').value='all';}let filtered=all,scenes=[],current=0;function build(){const g=$('#v-group').value;filtered=g==='range'?all.slice(start-1,end):all.filter(w=>g==='all'||g==='focus'&&f.includes(w.en)||String(w.group)===g);const url=new URL(location.href);if(g!=='range'){url.searchParams.delete('start');url.searchParams.delete('end');}history.replaceState(null,'',url);scenes=[];filtered.forEach((w,i)=>{scenes.push({word:w,reveal:false},{word:w,reveal:true});if((i+1)%3===0&&i<filtered.length-1)scenes.push({break:true});});current=0;draw();}function draw(){const scene=scenes[current];$('#v-position').textContent=(current+1)+' / '+scenes.length;$('#v-prev').disabled=current===0;$('#v-next').disabled=current===scenes.length-1;$('#v-card').hidden=!!scene.break;$('#v-break').hidden=!scene.break;if(scene.break)return;const w=scene.word;$('#v-source').textContent='Band II · Core II · Group '+w.group+' · '+w.position+' · '+w.pos;$('#v-word').textContent=w.en;$('#v-example').textContent=w.ex_en||'';$('#v-meaning').textContent=scene.reveal?w.mean_he:'';$('#v-translation').textContent=scene.reveal?w.ex_he:'';$('#v-hint').textContent=scene.reveal?'בדקו מול הניסיון שלכם. בהמשך עוברים לערך הבא.':'נסו להסביר לפני המעבר לשקף התרגום.';$('#v-original').href='https://englishfornoar.co.il/band-ii/groups/group-'+w.group+'.html';$('#vocab-status').textContent=filtered.length+' ערכים במסלול. התרגומים והדוגמאות הועתקו מרשומות המקור ללא שינוי.';}moveVocab=d=>{current=Math.max(0,Math.min(current+d,scenes.length-1));draw();};$('#v-prev').onclick=()=>moveVocab(-1);$('#v-next').onclick=()=>moveVocab(1);$('#v-group').onchange=build;build();}).catch(e=>{$('#vocab-status').textContent='קובץ המילים לא נטען. השתמשו בקישורי שלוש קבוצות המקור למטה.';});}\ndocument.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const d=['ArrowLeft','ArrowUp'].includes(e.key)?1:['ArrowRight','ArrowDown'].includes(e.key)?-1:0;if(d&&(slides.length||moveVocab)){e.preventDefault();if(slides.length)showDeck(deckIndex+d);else moveVocab(d);}if(slides.length&&['Home','End'].includes(e.key)){e.preventDefault();showDeck(e.key==='Home'?0:slides.length-1);}});function bindSwipes(zone,move){let gesture=null,ignoreUntil=0;function canScroll(target,dy){for(let el=target;el;el=el.parentElement){const overflow=getComputedStyle(el).overflowY;if((el===document.scrollingElement||/auto|scroll/.test(overflow))&&el.scrollHeight>el.clientHeight+2){if(dy<0&&el.scrollTop+el.clientHeight<el.scrollHeight-2||dy>0&&el.scrollTop>2)return true;}}return false;}zone.addEventListener('touchstart',e=>{gesture=null;if(e.touches.length!==1||e.target.closest('button,a,input,textarea,select,[role=button]'))return;gesture={x:e.touches[0].clientX,y:e.touches[0].clientY,target:e.target,done:false};},{passive:true});zone.addEventListener('touchmove',e=>{if(!gesture||gesture.done||e.touches.length!==1)return;const dx=e.touches[0].clientX-gesture.x,dy=e.touches[0].clientY-gesture.y;if(Math.max(Math.abs(dx),Math.abs(dy))<55)return;gesture.done=true;const vertical=Math.abs(dy)>Math.abs(dx);if(vertical&&canScroll(gesture.target,dy))return;e.preventDefault();ignoreUntil=Date.now()+450;move((vertical?dy:dx)<0?1:-1);},{passive:false});zone.addEventListener('touchend',()=>gesture=null,{passive:true});zone.addEventListener('touchcancel',()=>gesture=null,{passive:true});zone.addEventListener('click',e=>{if(Date.now()<ignoreUntil){e.preventDefault();e.stopImmediatePropagation();}},true);}\nconst zone=$('#vocab')||$('.deck');if(zone)bindSwipes(zone,d=>{if(slides.length)showDeck(deckIndex+d);else if(moveVocab)moveVocab(d);});\npaint();if(!storage)say('השמירה המקומית אינה זמינה; התרגול עדיין פתוח.');})();"
(OUT/'unit.js').write_text(JS)

def link(href,text,primary=False):
    return f'<a class="button {"primary" if primary else ""}" data-track href="{esc(href,quote=True)}">{text}</a>'
def check(key,text):
    return f'<label class="check"><input type="checkbox" data-save="{key}"><span>{text}</span></label>'
def answer(text):
    return f'<details class="answer"><summary>תשובה אפשרית — פתחו אחרי ניסיון</summary>{text}</details>'
def prompt(key,question,model,extra=''):
    return f'<div class="work"><label class="field-label en" lang="en" for="{key}">{question}</label>{extra}<textarea id="{key}" data-save="{key}" aria-label="Your answer"></textarea>{answer(model)}</div>'
def page(filename,title,body,kind=''):
    html=f'''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#081423"><title>{esc(title)} · כיתה ט׳ · Unit 1</title><link rel="stylesheet" href="unit.css?v={VERSION}"><script defer src="unit.js?v={VERSION}"></script></head><body data-page="{kind}"><main class="wrap"><header class="top"><a href="../../#grade9">← כיתה ט׳</a><a class="brand" href="./">Unit 1 · Communication & Human Connection</a></header><nav class="tabs" aria-label="חלקי היחידה">{link('./','מפגשים')}{link('student-preparation.html','חזרה בבית')}{link('resources.html','כל החומרים')}{link('teacher.html','מדריך למורה')}</nav><div id="status" role="status" aria-live="polite"></div>{body}<footer class="footer">נוצר: י״א בתשרי תשפ״ז · 22.9.2026 · כיתה ט׳1 · Teachers<br>השלמת משימות ותשובות נשמרות רק בדפדפן הזה. אין כאן שליחה למורה או סנכרון בין מכשירים. קישורים לאתר אוצר המילים כפופים להתנהגות האתר המקושר.</footer></main></body></html>'''
    (OUT/filename).write_text(html)

