report={'generatedPages':sorted(p.name for p in OUT.glob('*.html')),'vocabularyCount':len(words),'groups':manifest['sources'],'focusCount':len(focus),'storySentences':len(sentences),'modelWordCount':model_count,'meetingMinutes':[{k:m[k] for k in ('n','dur','active')} for m in meetings],'dateStatus':'four dated learning meetings','originalStoryUnchanged':hashlib.sha256(source.read_bytes()).hexdigest()==manifest['storySha256']}
assert report['originalStoryUnchanged']
for p in OUT.glob('*.html'):
    s=BeautifulSoup(p.read_text(),'html.parser')
    ids=[x['id'] for x in s.select('[id]')]
    assert len(ids)==len(set(ids)),f'Duplicate ID: {p}'
    for a in s.select('a[href]'):
        h=a['href'].split('#')[0].split('?')[0]
        if not h or re.match(r'^[a-z]+:',h):continue
        target=(p.parent/h)
        assert target.exists(),f'Broken local link: {p}: {h}'
(OUT/'build-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
print(json.dumps(report,ensure_ascii=False,indent=2))
